"""Date-window membership for the date_window fixture."""

from __future__ import annotations


def _is_leap_year(year: int) -> bool:
    """Check if a year is a leap year."""
    return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)


def _parse_date(date_str: str) -> tuple[int, int, int]:
    """Parse and validate an ISO date string (YYYY-MM-DD).

    Raises ValueError if the date is malformed or invalid.
    Returns a tuple of (year, month, day).
    """
    # Check format: must be exactly 10 characters
    if len(date_str) != 10:
        raise ValueError(f"Invalid date format: {date_str}")

    # Check separators
    if date_str[4] != '-' or date_str[7] != '-':
        raise ValueError(f"Invalid date format: {date_str}")

    # Parse components
    try:
        year_str, month_str, day_str = date_str.split('-')
        year = int(year_str)
        month = int(month_str)
        day = int(day_str)
    except (ValueError, AttributeError):
        raise ValueError(f"Invalid date format: {date_str}")

    # Validate ranges and zero-padding
    if len(year_str) != 4 or year < 1:
        raise ValueError(f"Invalid date format: {date_str}")
    if len(month_str) != 2 or month < 1 or month > 12:
        raise ValueError(f"Invalid date format: {date_str}")
    if len(day_str) != 2 or day < 1:
        raise ValueError(f"Invalid date format: {date_str}")

    # Days per month
    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    # Adjust for leap year
    if _is_leap_year(year):
        days_in_month[1] = 29

    # Validate day
    if day > days_in_month[month - 1]:
        raise ValueError(f"Invalid date format: {date_str}")

    return (year, month, day)


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window."""

    # Parse and validate target date
    target = _parse_date(target_date)

    # Parse, validate, and check all windows
    for start_str, end_str in windows:
        start = _parse_date(start_str)
        end = _parse_date(end_str)

        # Validate that start <= end
        if start > end:
            raise ValueError(f"Invalid window: start {start_str} is after end {end_str}")

        # Check if target is within this window (inclusive on both ends)
        if start <= target <= end:
            return True

    return False
